using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: discriminator property renamed from "Discriminator" to "$type".
            // Revert to EF8 property name for compatibility with existing 500K documents
            // and direct SQL queries that reference c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: id format changed from "EntityType|Key" to just "Key".
            // Map a shadow property to the JSON "id" using the old EF8 format so existing
            // documents with "Product|123" ids can still be read/queried.
            entity.Property<string>("__id")
                .ToJsonProperty("id")
                .ValueGeneratedOnAdd();

            entity.HasIndex(p => p.Sku);
        });
    }

    public override int SaveChanges()
    {
        SetLegacyIds();
        return base.SaveChanges();
    }

    public override Task<int> SaveChangesAsync(
        System.Threading.CancellationToken cancellationToken = default)
    {
        SetLegacyIds();
        return base.SaveChangesAsync(cancellationToken);
    }

    // Synthesize the EF8-era "EntityType|Key" id format for new documents.
    private void SetLegacyIds()
    {
        foreach (var entry in ChangeTracker.Entries<Product>()
            .Where(e => e.State == EntityState.Added))
        {
            entry.Property("__id").CurrentValue = $"Product|{entry.Entity.Id}";
        }
    }
}

